      original=dict(gameplay=['GAME:RunGameFromPassword actor erase 013B:0CC2..0D0F, draw 013B:0DF3..0E39, overlay 013B:0F60..0F89'],demo=['GAME:EraseDemoSprites 013B:0AB1','GAME:DrawDemoSprites 013B:0A58'],reset='GAME:ResetSpriteEraseState actor loop 013B:0B65..0B70; retained other contributions at013B:0B4F',l1=['c/scene.c','c/demo_scripts.c']),
      native=dict(files=names,header=names[0],functions=['actor_render_apply'],build='python verif/render_history_build.py'),
