        cert['evidence'] += [evidence('Eight complete 16-bit scalar slices','A','python verif/render_history_cases.py','PASS 524288 finite slice comparisons','All65536 raw X/Y words for each draw mode, and previousY/erase-sprite words for each erase mode; every other input fixed within each slice. This covers the slices, not the Cartesian slot domain.'),evidence('Small domains and generated slot states','C','python verif/render_history_cases.py',cases['stdout'].strip(),'695552 total inclusive of finite slices: full small hidden/clip/overlay boundary grid and16000x6 generated all-slot cases, including abnormal service returns.'),evidence('Behavioral and protocol controls','C','python verif/render_history_mutants.py; python verif/render_history_bound.py','All19 mutants DETECTED; insufficient actual sequence unwind FAIL','Private history, generation, signedness, hidden markers, overlay guard/order/offsets, reset and native-only request/store mutations are compiled and behaviorally rejected; compiler errors are not detection.'),evidence('Real demo-to-gameplay handoff and both pages','C','python verif/render_history_cross_mode.py','PASS26 actual native/literal boundaries and four page cycles; zero fallback','Two independent DLLs, actual loader/bootstrap/reset/stone update and literal inline draw/erase/overlay, actual pixel blits/page swap. Full RAM, complete registers/flags and device structures agree.'),evidence('L0 -> composed routine suites','C','python verif/render_history_integration.py --whole --local-reference',f'PASS{len(integration["cases"])} routine cases','Maintained demo_scripts/game_services/actors_states/actors/render/scene normal and poisoned inputs; all accepted native units plus this bridge.'),evidence('Maintained whole-game scenarios','D','python verif/render_history_integration.py --whole --local-reference','PASS20 scenarios, zero actor-render compatibility','Per-scenario six-operation slot counts and independent ASM caller coverage are recorded. high-score/password have zero entries; the other18 reach at least one operation.'),evidence('Scratch host promotion','D','python verif/render_history_host.py','PASS actual closure/build/native check,20 scenarios and256-frame smoke','Clean committed baseline plus owned overlay, only scratch actor_render promoted; unchanged actual CLI tools.')]
        cert['proposed_status']='migrated';cert['proposed_status_reason']='All23 current actual-C profiles, finite slices, generated/small-domain comparisons,19 mutation controls, full cross-mode/page trace, routine/scenario integration and actual scratch host promotion pass. Outer machine/pixel composition retains C/D scope.'
